    /// Generic class to describe the JsonRpc request package
    /// </summary>
    public class JsonRpcRequest<T0, T1, TParams>
      where T0 : AbstractRequestDataAttributes
      where T1 : AbstractRequestData<T0>
      where TParams : JsonRpcRequestParams<T0, T1>
    {
        [JsonProperty("version", NullValueHandling = NullValueHandling.Include)]
        [Required]
        public string Version { get; } = "1.1";
        [JsonProperty("method", Required = Required.Always, NullValueHandling = NullValueHandling.Include)]
        [Required]
        public string Method { get; }
        [JsonProperty("params")]
        public TParams Params { get; set; }

        public JsonRpcRequest(string method)
        {
            this.Method = method;
        }
    }

